toolsJs:
(function () {
    // --- Tool 1: lucky number pairs by birth day ---
    var suggestBtn = document.getElementById('suggestBtn');
    var suggestionResult = document.getElementById('suggestionResult');
    var birthDaySelect = document.getElementById('birthDaySelect');

    var dailyPairs = {
        0: { day: 'วันอาทิตย์', pairs: '36, 45, 56', desc: 'เสริมเสน่ห์, การเจรจา, การเงิน และความรัก' },
        1: { day: 'วันจันทร์', pairs: '24, 46, 63', desc: 'เสริมเมตตามหานิยม, การค้าขาย, เจรจาสำเร็จ' },
        2: { day: 'วันอังคาร', pairs: '39, 47, 78', desc: 'เสริมพลัง, ความกระตือรือร้น, และโชคลาภไม่คาดฝัน' },
        3: { day: 'วันพุธ (กลางวัน)', pairs: '24, 42, 56', desc: 'เสริมการเจรจา, สติปัญญา, และการเงินที่คล่องตัว' },
        4: { day: 'วันพฤหัสบดี', pairs: '15, 51, 59', desc: 'เสริมบารมี, ผู้ใหญ่เอ็นดู, สติปัญญา, และความสำเร็จ' },
        5: { day: 'วันศุกร์', pairs: '23, 32, 66', desc: 'เสริมเสน่ห์, ความรัก, และการเงินที่โดดเด่น' },
        6: { day: 'วันเสาร์', pairs: '78, 87, 89', desc: 'เสริมอำนาจบารมี, การเงินก้อนใหญ่, และความมั่นคง' },
        8: { day: 'วันพุธ (กลางคืน)', pairs: '28, 82, 78', desc: 'เสริมเรื่องโชคลาภ, เงินก้อนใหญ่, และความกล้าได้กล้าเสีย' }
    };

    suggestBtn.addEventListener('click', function () {
        if (!birthDaySelect.value) {
            suggestionResult.innerHTML = '<p class="tool-error">กรุณาเลือกวันเกิดของคุณ</p>';
            suggestionResult.hidden = false;
            return;
        }
        var data = dailyPairs[parseInt(birthDaySelect.value, 10)];
        suggestionResult.innerHTML =
            '<h4 class="tool-result-title">สำหรับคนเกิด ' + data.day + '</h4>' +
            '<p class="tool-result-line">คู่เลขมงคลที่แนะนำคือ <strong class="tool-result-highlight">' + data.pairs + '</strong></p>' +
            '<p class="tool-result-desc">' + data.desc + '</p>';
        suggestionResult.hidden = false;
    });

    // --- Tool 2: phone number sum analysis ---
    var analyzeBtn = document.getElementById('analyzeBtn');
    var analysisResult = document.getElementById('analysisResult');
    var phoneInput = document.getElementById('phoneNumber');

    var sumMeanings = {
        14: { grade: 'ดีมาก', title: 'สติปัญญาและชื่อเสียง', fortune: 'มีโชคจากการเจรจา เดินทางไกล', work: 'ประสบความสำเร็จสูง มีชื่อเสียง ได้รับการยอมรับ', health: 'แข็งแรงดี ระวังพักผ่อนน้อย', love: 'มีเสน่ห์จากการพูดคุย' },
        15: { grade: 'ดีมาก', title: 'เสน่ห์และโชคการเงิน', fortune: 'มีโชคด้านการเงินไม่ขาดสาย', work: 'ผู้ใหญ่รักใคร่เอ็นดู สนับสนุนเสมอ', health: 'สุขภาพดีไม่มีปัญหา', love: 'มีเสน่ห์ ดึงดูดเพศตรงข้าม' },
        24: { grade: 'ดีมาก', title: 'เมตตามหานิยม', fortune: 'การเงินคล่องตัว มีคนช่วยเหลือเสมอ', work: 'เจรจาค้าขายสำเร็จ ผู้คนเชื่อถือ', health: 'แข็งแรง สดใส', love: 'เป็นที่รักของคนรอบข้าง' },
        28: { grade: 'ควรเลี่ยง', title: 'ใจใหญ่ ใจนักเลง', fortune: 'ได้เงินก้อนใหญ่ แต่ก็เสียเงินก้อนใหญ่', work: 'เหมาะกับงานเสี่ยงๆ แต่ต้องระวังเรื่องบริวาร', health: 'ระวังอุบัติเหตุเกี่ยวกับความเร็ว', love: 'ความรักร้อนแรง มีปากเสียงง่าย' },
        36: { grade: 'ดีมาก', title: 'ความรักสดใส การเงินดี', fortune: 'มีโชคทางการเงินและความรัก', work: 'งานเกี่ยวกับความสวยความงามจะรุ่ง', health: 'แข็งแรง มีเสน่ห์', love: 'ความรักสมหวัง สดชื่น' },
        41: { grade: 'ดีมาก', title: 'วาจาเป็นทรัพย์', fortune: 'หาเงินเก่งจากการพูด', work: 'เหมาะกับงานที่ต้องใช้คำพูด เช่น นักขาย พิธีกร', health: 'แข็งแรง คล่องแคล่ว', love: 'พูดจาดี มีคนรักใคร่' },
        42: { grade: 'ดีมาก', title: 'การเงินคล่องตัว', fortune: 'การเงินดีมาก มีคนอุปถัมภ์', work: 'ทำธุรกิจส่วนตัวจะรุ่งเรือง', health: 'สุขภาพดี', love: 'มีเสน่ห์ อ่อนหวาน' },
        45: { grade: 'ดีมาก', title: 'เทพีแห่งโชค', fortune: 'มีโชคลาภเสมอ ชีวิตราบรื่น', work: 'ผู้ใหญ่เมตตา ทำงานราชการดี', health: 'แข็งแรง อายุยืน', love: 'มีคู่ครองที่ดี คอยสนับสนุน' },
        51: { grade: 'ดีมาก', title: 'พลังแห่งความสำเร็จ', fortune: 'มีโชคจากความสามารถของตนเอง', work: 'เป็นผู้นำ มีบารมี คนนับถือ', health: 'แข็งแรง สมบูรณ์', love: 'เป็นที่เคารพของคนรัก' },
        56: { grade: 'ดีมาก', title: 'ปัญญาสร้างทรัพย์', fortune: 'การเงินดีมาก มีเงินเก็บ', work: 'ฉลาด วางแผนเก่ง ทำงานสำเร็จ', health: 'สุขภาพดี', love: 'ความรักมั่นคง อบอุ่น' },
        59: { grade: 'ดีมาก', title: 'สิ่งศักดิ์สิทธิ์คุ้มครอง', fortune: 'มีโชคลาภไม่คาดฝัน', work: 'มีลางสังหรณ์แม่นยำ เหมาะกับงานต่างประเทศ', health: 'แข็งแรง แคล้วคลาดปลอดภัย', love: 'มีความรักที่เข้าใจกัน' },
        63: { grade: 'ดีมาก', title: 'เสน่ห์และการเงิน', fortune: 'เงินทองไม่ขาดมือ มีคนเปย์', work: 'งานด้านบันเทิง ความงามจะดีมาก', health: 'แข็งแรง มีเสน่ห์', love: 'เสน่ห์แรง มีคนเข้าหาเยอะ' }
    };

    function getGoodSums() {
        return Object.keys(sumMeanings).filter(function (sum) {
            return sumMeanings[sum].grade === 'ดีมาก';
        }).map(Number);
    }

    function suggestNumbers(badSum) {
        var goodSums = getGoodSums();
        var suggestions = goodSums.sort(function (a, b) {
            return Math.abs(a - badSum) - Math.abs(b - badSum);
        }).slice(0, 3);

        var html = '<div class="tool-suggestions"><h4 class="tool-suggestions-title">เบอร์มงคลที่แนะนำ (ผลรวมใกล้เคียง)</h4><ul class="tool-suggestions-list">';
        suggestions.forEach(function (sum) {
            html += '<li><strong>ผลรวม ' + sum + ':</strong> ' + sumMeanings[sum].title + '</li>';
        });
        html += '</ul></div>';
        return html;
    }

    analyzeBtn.addEventListener('click', function () {
        var number = phoneInput.value;
        if (!/^\d{10}$/.test(number)) {
            analysisResult.innerHTML = '<p class="tool-error">กรุณากรอกเบอร์โทรศัพท์ 10 หลักให้ถูกต้อง</p>';
            analysisResult.hidden = false;
            return;
        }

        var sum = number.split('').reduce(function (acc, digit) {
            return acc + parseInt(digit, 10);
        }, 0);
        var resultData = sumMeanings[sum];
        var htmlResult = '';

        if (resultData) {
            var gradeClass = resultData.grade === 'ดีมาก' ? 'tool-grade-good' : (resultData.grade === 'ควรเลี่ยง' ? 'tool-grade-bad' : 'tool-grade-mid');
            htmlResult +=
                '<h4 class="tool-result-title">ผลการวิเคราะห์</h4>' +
                '<p class="tool-result-line">ผลรวมของเบอร์โทรศัพท์คือ <strong class="tool-result-highlight">' + sum + '</strong></p>' +
                '<p class="tool-result-line">ระดับ: <strong class="' + gradeClass + '">' + resultData.grade + '</strong> - ' + resultData.title + '</p>' +
                '<div class="tool-result-details"><ul class="tool-result-list">' +
                '<li><strong>โชคลาภ:</strong> ' + resultData.fortune + '</li>' +
                '<li><strong>การงาน:</strong> ' + resultData.work + '</li>' +
                '<li><strong>สุขภาพ:</strong> ' + resultData.health + '</li>' +
                '<li><strong>ความรัก:</strong> ' + resultData.love + '</li>' +
                '</ul></div>';
            if (resultData.grade === 'ควรเลี่ยง' || resultData.grade === 'ปานกลาง') {
                htmlResult += suggestNumbers(sum);
            }
        } else {
            htmlResult =
                '<h4 class="tool-result-title">ผลการวิเคราะห์</h4>' +
                '<p class="tool-result-line">ผลรวมของเบอร์โทรศัพท์คือ <strong class="tool-result-highlight">' + sum + '</strong></p>' +
                '<p class="tool-result-line">ระดับ: <strong class="tool-grade-mid">ปานกลาง</strong></p>' +
                '<p class="tool-result-desc">เป็นผลรวมที่ไม่มีความหมายโดดเด่นเป็นพิเศษ สามารถใช้งานได้ทั่วไป ไม่ส่งผลดีหรือผลเสียที่ชัดเจน</p>';
            htmlResult += suggestNumbers(sum);
        }

        analysisResult.innerHTML = htmlResult;
        analysisResult.hidden = false;
    });
})();
